/**
 * Digital Khatt mushaf data — real Unicode text pages for the
 * Digital Khatt renderer (Tarteel-parity step 1b, agent-2 PR).
 *
 * Two datasets, both generated by
 * scripts/generate-quran-mushaf-dk.py from the QUL word/layout
 * datasets ("Digital Khatt Quran script" word text + the matching
 * page/line layouts) and cross-checked line-by-line against this
 * repo's independent QPC V2 pipeline (identical line-kind and
 * ayah-end sequences on all 604 Madani pages):
 *
 *   - 'madani'  — Digital Khatt V2 script on the KFGQPC V2 1421H
 *     print layout: 604 pages × 15 lines.
 *   - 'indopak' — Digital Khatt IndoPak script on the IndoPak
 *     15-line layout: 610 pages × 15 lines.
 *
 * A page's lines are typed exactly like the printed page: surah
 * header ('h'), Basmala ('b' — no words; the Basmala is the page's
 * `basmala` string, rendered in the font's dedicated `basm`
 * feature), and text lines ('x') of word entries. Word keys are
 * "surah:ayah:word" with the 1-based REAL-word ordinal (the same
 * convention as the V4 study data); ayah-end markers are their own
 * entries (key "surah:ayah:end", `m: 1`) whose text is the marker
 * itself (U+06DD + Arabic-Indic digits), exactly as the DK script
 * encodes them. Note the print convention the layout data follows:
 * when an ayah's last word ends a line, its marker token is the
 * FIRST word of the next line.
 *
 * Data provenance and licence status are recorded in
 * THIRD_PARTY_NOTICES.md and public/fonts/digital-khatt/README.md.
 */

export type DKMushafVariant = 'madani' | 'indopak';

export interface DKWord {
  /** "surah:ayah:word" (real-word ordinal) or "surah:ayah:end". */
  k: string;
  /** Global QUL word id (word_number_all), 1..83668. */
  g: number;
  /** The word's Digital Khatt script text (real Unicode). */
  x: string;
  /** 1 for ayah-end marker entries. */
  m?: 1;
}

export type DKLine =
  | { t: 'h'; s: number; x: string }
  | { t: 'b' }
  | { t: 'x'; c?: 1; words: DKWord[] };

export interface DKPage {
  n: number;
  /** Madani pages carry the standard juz/hizb; the IndoPak layout
      has no boundary data in this dataset, so both are null there. */
  juz: number | null;
  hizb: number | null;
  /** The Basmala in this variant's DK script spelling. */
  basmala: string;
  lines: DKLine[];
}

export const DK_PAGE_COUNTS: Record<DKMushafVariant, number> = {
  madani: 604,
  indopak: 610,
};

function pageUrl(variant: DKMushafVariant, page: number): string {
  return variant === 'madani'
    ? `/quran-mushaf-dk-pages/p${page}.json`
    : `/quran-mushaf-dk-indopak-pages/p${page}.json`;
}

function fullUrl(variant: DKMushafVariant): string {
  return variant === 'madani'
    ? '/quran-mushaf-dk.json'
    : '/quran-mushaf-dk-indopak.json';
}

const pagePromises = new Map<string, Promise<DKPage | null>>();
const fullPromises = new Map<DKMushafVariant, Promise<DKPage[] | null>>();

function loadFull(variant: DKMushafVariant): Promise<DKPage[] | null> {
  let p = fullPromises.get(variant);
  if (!p) {
    p = fetch(fullUrl(variant))
      .then((r) => (r.ok ? r.json() : null))
      .then((data: { pages?: DKPage[] } | null) =>
        data && Array.isArray(data.pages) ? data.pages : null,
      )
      .catch(() => null);
    fullPromises.set(variant, p);
  }
  return p;
}

/**
 * Load one DK page. Tries the per-page chunk first and falls back
 * to the full dataset file (same pattern as the V2 loaders).
 * Resolves null when neither is available — the caller then keeps
 * the standard renderer; a DK page is never faked from other data.
 */
export function loadDKPage(
  variant: DKMushafVariant,
  page: number,
): Promise<DKPage | null> {
  const max = DK_PAGE_COUNTS[variant];
  if (!Number.isInteger(page) || page < 1 || page > max) {
    return Promise.resolve(null);
  }
  const cacheKey = `${variant}:${page}`;
  let p = pagePromises.get(cacheKey);
  if (!p) {
    p = fetch(pageUrl(variant, page))
      .then((r) => (r.ok ? (r.json() as Promise<DKPage>) : null))
      .catch(() => null)
      .then((pg) => {
        if (pg && pg.n === page && Array.isArray(pg.lines)) return pg;
        return loadFull(variant).then(
          (pages) => pages?.find((x) => x.n === page) ?? null,
        );
      });
    pagePromises.set(cacheKey, p);
  }
  return p;
}
